#!/usr/bin/env bash
# description: Every path operation function must declare a response_model or a return type annotation FastAPI can infer, so OpenAPI generation and response filtering work correctly.
# scope: all
set -euo pipefail

root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"

python3 - "$root" <<'PYEOF'
import re, sys, pathlib

root = pathlib.Path(sys.argv[1])
decorator_re = re.compile(r'@(?:app|router)\.(get|post|put|patch|delete)\(([^)]*)\)')
def_re = re.compile(r'^\s*(?:async\s+)?def\s+\w+\(.*\)\s*(->\s*[\w\[\], .\'\"]+)?\s*:')

violations = []
for path in root.rglob('*.py'):
    parts = path.parts
    if 'tests' in parts or path.name.startswith('test_'):
        continue
    try:
        lines = path.read_text().splitlines()
    except (UnicodeDecodeError, OSError):
        continue
    for i, line in enumerate(lines):
        m = decorator_re.search(line)
        if not m:
            continue
        args = m.group(2)
        if 'response_model' in args:
            continue
        j = i + 1
        found_return = False
        while j < len(lines) and j < i + 6:
            dm = def_re.match(lines[j])
            if dm:
                found_return = dm.group(1) is not None
                break
            j += 1
        if not found_return:
            violations.append(f"{path.relative_to(root)}:{i+1}")

if violations:
    print('Path operations without response_model or a return type annotation:')
    for v in violations:
        print(f'  {v}')
    sys.exit(1)
sys.exit(0)
PYEOF
